"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  buildXlsxSourceFromCompact,
  resolveXlsxSheetChange,
  XlsxSourceCache,
  type CompactSheet,
  type XlsxSheetMeta,
  type XlsxSource,
} from "@/lib/xlsx-workbook"
import {
  type XlsxWorkerRequest,
  type XlsxWorkerResponse,
} from "@/lib/xlsx-worker-protocol"
import { XlsxGrid, XlsxGridSkeleton } from "@/components/ui/xlsx-grid"
import { XlsxSheetTabs } from "@/components/ui/xlsx-sheet-tabs"
import { XlsxToolbar, XlsxToolbarSkeleton } from "@/components/ui/xlsx-toolbar"
import {
  resolveLoadedScrollTarget,
  toInternalCellRef,
  type InternalXlsxCellRef,
  type PendingXlsxScrollTarget,
  type PublicXlsxCellRef,
  type XlsxScrollRequest,
} from "@/components/ui/xlsx-viewer-scroll"

const sourceCache = new XlsxSourceCache({ maxEntries: 4 })

async function buildXlsxSource(src: string): Promise<XlsxSource> {
  const response = await fetch(src)
  if (!response.ok) {
    throw new Error(`Failed to load spreadsheet: ${response.status}`)
  }
  const buffer = await response.arrayBuffer()
  return buildXlsxSourceFromCompact(await parseWorkbookInWorker(buffer))
}

function parseWorkbookInWorker(buffer: ArrayBuffer): Promise<CompactSheet[]> {
  return new Promise((resolve, reject) => {
    if (typeof Worker === "undefined") {
      reject(new Error("Web Workers are unavailable in this environment"))
      return
    }

    const worker = new Worker(
      new URL("./xlsx-viewer.worker", import.meta.url),
      { type: "module" }
    )
    worker.onmessage = (event: MessageEvent<XlsxWorkerResponse>) => {
      worker.terminate()
      if (event.data.type === "workbook") {
        resolve(event.data.sheets)
      } else {
        reject(new Error(event.data.message))
      }
    }
    worker.onerror = (event) => {
      worker.terminate()
      reject(new Error(event.message || "Spreadsheet worker failed"))
    }
    const request: XlsxWorkerRequest = { type: "parse_workbook", buffer }
    worker.postMessage(request, [buffer])
  })
}

function getXlsxSource(src: string): Promise<XlsxSource> {
  return sourceCache.get(src, () => buildXlsxSource(src))
}

/** Client gate without an effect: false during SSR, true after hydration. */
function useIsClient() {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false
  )
}

export interface XlsxViewerProps {
  /** URL of the .xlsx/.xls (same-origin or CORS-enabled). */
  src: string
  className?: string
  toolbar?: boolean
  downloadFileName?: string
  /** Sheet shown first. Defaults to 0. */
  defaultSheetIndex?: number
  /** Fired with the active sheet index on tab switch and imperative sheet changes. */
  onSheetChange?: (index: number) => void
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean
  /** Rendered as a full-width strip directly below the toolbar. */
  header?: React.ReactNode
  /** Rendered as a left rail alongside the grid. */
  aside?: React.ReactNode
  /** Public compatibility coordinates: 0-based row + column on `sheet`. */
  activeCell?: XlsxCellRef | null
  /**
   * Render the scrolling grid inside a shadow root, isolating it from host page
   * style invalidation while preserving inherited theme variables.
   */
  isolateStyles?: boolean
}

export type XlsxCellRef = PublicXlsxCellRef

export interface XlsxViewerHandle {
  scrollToCell: (
    sheet: number,
    row: number,
    col: number,
    options?: { behavior?: ScrollBehavior }
  ) => void
  getViewportElement: () => HTMLDivElement | null
}

export const XlsxViewer = React.forwardRef<XlsxViewerHandle, XlsxViewerProps>(
  function XlsxViewer(props, ref) {
    const isClient = useIsClient()
    if (!isClient) {
      return (
        <XlsxViewerFallback className={props.className} bare={props.bare} />
      )
    }
    return (
      <XlsxErrorBoundary className={props.className} resetKey={props.src}>
        <React.Suspense
          fallback={
            <XlsxViewerFallback className={props.className} bare={props.bare} />
          }
        >
          <XlsxViewerSession key={props.src} {...props} forwardedRef={ref} />
        </React.Suspense>
      </XlsxErrorBoundary>
    )
  }
)

function XlsxViewerSession({
  src,
  className,
  toolbar = true,
  downloadFileName,
  defaultSheetIndex = 0,
  onSheetChange,
  bare = false,
  header,
  aside,
  activeCell,
  isolateStyles = false,
  forwardedRef,
}: XlsxViewerProps & {
  forwardedRef?: React.ForwardedRef<XlsxViewerHandle>
}) {
  const [activeSheetIndex, setActiveSheetIndex] = React.useState(
    Math.max(0, defaultSheetIndex)
  )
  const [scale, setScale] = React.useState(1)
  const [scrollRequest, setScrollRequest] =
    React.useState<XlsxScrollRequest | null>(null)
  const [pendingScrollTarget, setPendingScrollTarget] =
    React.useState<PendingXlsxScrollTarget | null>(null)
  const scrollNonce = React.useRef(0)
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null)
  const [sheets, setSheets] = React.useState<XlsxSheetMeta[] | null>(null)

  const reportSource = React.useCallback((source: XlsxSource) => {
    setSheets(source.sheets)
    setActiveSheetIndex((sheetIndex) =>
      clamp(sheetIndex, 0, Math.max(0, source.sheets.length - 1))
    )
  }, [])

  const setLoadedSheetIndex = React.useCallback(
    (sheetIndex: number) => {
      const change = resolveXlsxSheetChange({
        activeSheet: activeSheetIndex,
        requestedSheet: sheetIndex,
        sheetCount: sheets?.length,
      })
      if (!change.accepted) return false
      if (change.changed) {
        setActiveSheetIndex(change.sheetIndex)
        onSheetChange?.(change.sheetIndex)
      }
      return true
    },
    [activeSheetIndex, onSheetChange, sheets]
  )

  const issueLoadedScrollTarget = React.useCallback(
    (target: PendingXlsxScrollTarget) => {
      if (!sheets) return false

      const resolved = resolveLoadedScrollTarget({
        activeSheetIndex,
        target,
        sheets,
      })
      if (!resolved) return false

      if (resolved.changed) {
        setActiveSheetIndex(resolved.sheetIndex)
        onSheetChange?.(resolved.sheetIndex)
      }

      scrollNonce.current += 1
      setScrollRequest({
        ...resolved.request,
        nonce: scrollNonce.current,
      })
      return true
    },
    [activeSheetIndex, onSheetChange, sheets]
  )

  React.useEffect(() => {
    if (!pendingScrollTarget || !sheets) return
    setPendingScrollTarget(null)
    issueLoadedScrollTarget(pendingScrollTarget)
  }, [issueLoadedScrollTarget, pendingScrollTarget, sheets])

  React.useImperativeHandle(
    forwardedRef,
    () => ({
      scrollToCell: (sheet, row, col, options) => {
        const target = toInternalCellRef({ sheet, row, col })
        if (!target) return

        const pendingTarget = {
          ...target,
          behavior: options?.behavior ?? "smooth",
        }
        if (!sheets) {
          setPendingScrollTarget(pendingTarget)
          return
        }

        issueLoadedScrollTarget(pendingTarget)
      },
      getViewportElement: () => viewportElementRef.current,
    }),
    [issueLoadedScrollTarget, sheets]
  )

  const isReady = sheets != null
  const activeSheet = sheets?.[activeSheetIndex]
  const activeCellTarget = toInternalCellRef(activeCell)
  const zoom = (factor: number) =>
    setScale((value) => clamp(value * factor, 0.25, 5))

  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="xlsx-viewer"
    >
      {toolbar ? (
        <XlsxToolbar
          src={src}
          downloadFileName={downloadFileName}
          sheet={activeSheet}
          isReady={isReady}
          scale={scale}
          onZoomOut={() => zoom(1 / 1.2)}
          onZoomIn={() => zoom(1.2)}
          onResetZoom={() => setScale(1)}
        />
      ) : null}

      <div className="flex min-h-0 flex-1">
        {aside ? (
          <div data-slot="xlsx-viewer-aside" className="flex-shrink-0">
            {aside}
          </div>
        ) : null}
        <div className="flex min-h-0 min-w-0 flex-1 flex-col">
          {header ? <div data-slot="xlsx-viewer-header">{header}</div> : null}
          <React.Suspense fallback={<XlsxGridSkeleton />}>
            <XlsxSheet
              src={src}
              activeSheetIndex={activeSheetIndex}
              scale={scale}
              onReportSource={reportSource}
              activeCell={activeCellTarget}
              scrollRequest={scrollRequest}
              isolateStyles={isolateStyles}
              viewportRef={viewportElementRef}
            />
          </React.Suspense>
        </div>
      </div>

      {sheets ? (
        <XlsxSheetTabs
          sheets={sheets}
          activeSheetIndex={activeSheetIndex}
          onSelectSheet={setLoadedSheetIndex}
        />
      ) : null}
    </div>
  )
}

function XlsxSheet({
  src,
  activeSheetIndex,
  scale,
  onReportSource,
  activeCell,
  scrollRequest,
  isolateStyles,
  viewportRef,
}: {
  src: string
  activeSheetIndex: number
  scale: number
  onReportSource: (source: XlsxSource) => void
  activeCell?: InternalXlsxCellRef | null
  scrollRequest?: XlsxScrollRequest | null
  isolateStyles: boolean
  viewportRef?: React.RefObject<HTMLDivElement | null>
}) {
  const source = React.use(getXlsxSource(src))

  React.useEffect(() => {
    onReportSource(source)
  }, [source, onReportSource])

  const sheetIndex = clamp(
    activeSheetIndex,
    0,
    Math.max(0, source.sheets.length - 1)
  )
  const sheet = source.sheets[sheetIndex]
  const getCell = React.useCallback(
    (rowIndex: number, columnIndex: number) =>
      source.getCell(sheetIndex, rowIndex, columnIndex),
    [source, sheetIndex]
  )
  const activeCellInSheet =
    activeCell && activeCell.sheetIndex === sheetIndex
      ? { rowIndex: activeCell.rowIndex, columnIndex: activeCell.columnIndex }
      : null
  const scrollRequestInSheet =
    scrollRequest && scrollRequest.sheetIndex === sheetIndex
      ? scrollRequest
      : null

  return (
    <XlsxGrid
      key={sheetIndex}
      rowCount={sheet?.rowCount ?? 0}
      columnCount={sheet?.columnCount ?? 0}
      sheetName={sheet?.name ?? `Sheet ${sheetIndex + 1}`}
      getCell={getCell}
      scale={scale}
      activeCell={activeCellInSheet}
      scrollRequest={scrollRequestInSheet}
      isolateStyles={isolateStyles}
      viewportRef={viewportRef}
    />
  )
}

function XlsxViewerFallback({
  className,
  bare = false,
}: {
  className?: string
  bare?: boolean
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="xlsx-viewer"
    >
      <XlsxToolbarSkeleton />
      <div className="flex min-h-0 flex-1">
        <XlsxGridSkeleton />
      </div>
    </div>
  )
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

class XlsxErrorBoundary extends React.Component<
  { children: React.ReactNode; className?: string; resetKey?: unknown },
  { error: boolean }
> {
  state = { error: false }

  componentDidUpdate(prev: { resetKey?: unknown }) {
    if (prev.resetKey !== this.props.resetKey && this.state.error) {
      this.setState({ error: false })
    }
  }

  static getDerivedStateFromError() {
    return { error: true }
  }

  render() {
    if (this.state.error) {
      return (
        <div
          className={cn(
            "flex min-h-64 items-center justify-center rounded-xl border bg-muted/30 p-6 text-center text-sm text-muted-foreground",
            this.props.className
          )}
        >
          Couldn&apos;t load this spreadsheet.
        </div>
      )
    }
    return this.props.children
  }
}

"use client"

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"

import { xlsxColumnLabel, type XlsxCell } from "@/lib/xlsx-workbook"
import {
  XLSX_BASE_COLUMN_WIDTH,
  XLSX_BASE_FONT_SIZE,
  XLSX_BASE_GUTTER_WIDTH,
  XLSX_BASE_ROW_HEIGHT,
} from "@/components/ui/xlsx-grid-constants"
import {
  Spacer,
  XlsxGridRow,
  type XlsxGridColumnItem,
} from "@/components/ui/xlsx-grid-row"
import {
  HeaderAwareScrollbar,
  XLSX_SCROLLBAR_CSS,
} from "@/components/ui/xlsx-grid-scrollbar"
import { ScrollerShell } from "@/components/ui/xlsx-shadow-scope"

export { XlsxGridSkeleton } from "@/components/ui/xlsx-grid-skeleton"

export interface XlsxScrollRequest {
  sheetIndex: number
  rowIndex: number
  columnIndex: number
  behavior: ScrollBehavior
  nonce: number
}

interface XlsxGridCellRef {
  rowIndex: number
  columnIndex: number
}

export function XlsxGrid({
  rowCount,
  columnCount,
  getCell,
  sheetName,
  scale,
  activeCell,
  scrollRequest,
  isolateStyles,
  viewportRef,
}: {
  rowCount: number
  columnCount: number
  sheetName: string
  getCell: (rowIndex: number, columnIndex: number) => XlsxCell
  scale: number
  activeCell?: XlsxGridCellRef | null
  scrollRequest?: XlsxScrollRequest | null
  isolateStyles: boolean
  viewportRef?: React.RefObject<HTMLDivElement | null>
}) {
  const rowHeight = Math.round(XLSX_BASE_ROW_HEIGHT * scale)
  const columnWidth = Math.round(XLSX_BASE_COLUMN_WIDTH * scale)
  const gutterWidth = Math.round(XLSX_BASE_GUTTER_WIDTH * scale)
  const fontSize = XLSX_BASE_FONT_SIZE * scale

  const scrollRef = React.useRef<HTMLDivElement>(null)
  const setScrollElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      scrollRef.current = element
      if (viewportRef) viewportRef.current = element
    },
    [viewportRef]
  )

  const rowVirtualizer = useVirtualizer({
    count: rowCount,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => rowHeight,
    overscan: 30,
  })
  const columnVirtualizer = useVirtualizer({
    horizontal: true,
    count: columnCount,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => columnWidth,
    overscan: 30,
  })

  React.useEffect(() => {
    rowVirtualizer.measure()
    columnVirtualizer.measure()
  }, [rowHeight, columnWidth, rowVirtualizer, columnVirtualizer])

  const requestNonce = scrollRequest?.nonce
  React.useEffect(() => {
    if (!scrollRequest) return
    rowVirtualizer.scrollToIndex(scrollRequest.rowIndex, {
      align: "center",
      behavior: scrollRequest.behavior,
    })
    columnVirtualizer.scrollToIndex(scrollRequest.columnIndex, {
      align: "center",
      behavior: scrollRequest.behavior,
    })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [requestNonce])

  const virtualColumns = columnVirtualizer.getVirtualItems()
  const totalColumnSize = columnVirtualizer.getTotalSize()
  const { columnItems, leftPad, rightPad } = React.useMemo(() => {
    const left = virtualColumns.length ? virtualColumns[0].start : 0
    const right = virtualColumns.length
      ? totalColumnSize - virtualColumns[virtualColumns.length - 1].end
      : 0
    return {
      columnItems: virtualColumns.map((item) => ({
        columnIndex: item.index,
        size: item.size,
      })) as XlsxGridColumnItem[],
      leftPad: left,
      rightPad: right,
    }
  }, [virtualColumns, totalColumnSize])

  const gridTemplate = React.useMemo(
    () => buildGridTemplate({ gutterWidth, leftPad, columnItems, rightPad }),
    [gutterWidth, leftPad, columnItems, rightPad]
  )
  const totalWidth = gutterWidth + columnCount * columnWidth
  const virtualRows = rowVirtualizer.getVirtualItems()

  if (rowCount === 0 || columnCount === 0) {
    return (
      <div
        className="flex flex-1 items-center justify-center bg-card text-xs text-muted-foreground"
        role="status"
        aria-label={`${sheetName} is empty`}
      >
        Empty sheet
      </div>
    )
  }

  return (
    <div
      className="flex min-h-0 flex-1 flex-col bg-card"
      style={{ fontSize }}
      data-slot="xlsx-grid"
    >
      <ScrollerShell
        isolate={isolateStyles}
        className="relative min-h-0 flex-1"
      >
        <style>{XLSX_SCROLLBAR_CSS}</style>
        <div
          ref={setScrollElement}
          data-slot="xlsx-body"
          role="grid"
          aria-label={sheetName}
          aria-rowcount={rowCount}
          aria-colcount={columnCount}
          tabIndex={0}
          className="absolute inset-0 overflow-auto"
        >
          <div
            style={{
              width: totalWidth,
              minWidth: "100%",
              position: "relative",
            }}
          >
            <div
              className="sticky top-0 z-20 grid border-b"
              style={{
                gridTemplateColumns: gridTemplate,
                height: rowHeight,
                backgroundColor:
                  "color-mix(in oklab, var(--card) 92%, var(--foreground))",
              }}
              aria-hidden
            >
              <div
                className="sticky left-0 z-10 border-r bg-[color-mix(in_oklab,var(--card)_94%,var(--foreground))]"
                style={{ height: rowHeight }}
              />
              <Spacer width={leftPad} />
              {columnItems.map((item) => (
                <div
                  key={item.columnIndex}
                  className="flex items-center justify-center border-r font-medium text-muted-foreground last:border-r-0"
                >
                  {xlsxColumnLabel(item.columnIndex)}
                </div>
              ))}
              <Spacer width={rightPad} />
            </div>

            <div
              style={{
                position: "relative",
                height: rowVirtualizer.getTotalSize(),
              }}
            >
              {virtualRows.map((virtualRow) => (
                <XlsxGridRow
                  key={virtualRow.index}
                  rowIndex={virtualRow.index}
                  getCell={getCell}
                  gridTemplate={gridTemplate}
                  rowHeight={rowHeight}
                  columnItems={columnItems}
                  leftPad={leftPad}
                  rightPad={rightPad}
                  start={virtualRow.start}
                  activeColumnIndex={
                    activeCell?.rowIndex === virtualRow.index
                      ? activeCell.columnIndex
                      : null
                  }
                />
              ))}
            </div>
          </div>
        </div>
        <HeaderAwareScrollbar scrollRef={scrollRef} headerHeight={rowHeight} />
      </ScrollerShell>
    </div>
  )
}

function buildGridTemplate({
  gutterWidth,
  leftPad,
  columnItems,
  rightPad,
}: {
  gutterWidth: number
  leftPad: number
  columnItems: XlsxGridColumnItem[]
  rightPad: number
}) {
  const visibleColumns = columnItems
    .map((column) => `${column.size}px`)
    .join(" ")
  return [`${gutterWidth}px`, `${leftPad}px`, visibleColumns, `${rightPad}px`]
    .filter(Boolean)
    .join(" ")
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import type { XlsxCell } from "@/lib/xlsx-workbook"

export interface XlsxGridColumnItem {
  columnIndex: number
  size: number
}

export const XlsxGridRow = React.memo(function XlsxGridRow({
  rowIndex,
  getCell,
  gridTemplate,
  rowHeight,
  columnItems,
  leftPad,
  rightPad,
  start,
  activeColumnIndex,
}: {
  rowIndex: number
  getCell: (rowIndex: number, columnIndex: number) => XlsxCell
  gridTemplate: string
  rowHeight: number
  columnItems: XlsxGridColumnItem[]
  leftPad: number
  rightPad: number
  start: number
  activeColumnIndex?: number | null
}) {
  const style: React.CSSProperties = {
    gridTemplateColumns: gridTemplate,
    height: rowHeight,
    position: "absolute",
    top: 0,
    left: 0,
    width: "100%",
    transform: `translateY(${start}px)`,
  }
  return (
    <div
      className="group grid border-b hover:bg-muted/40"
      style={style}
      role="row"
      aria-rowindex={rowIndex + 1}
    >
      <div
        aria-hidden
        className="sticky left-0 z-[1] flex items-center justify-end border-r bg-card px-2 text-muted-foreground tabular-nums group-hover:bg-[color-mix(in_oklab,var(--card)_97%,var(--foreground))]"
      >
        {rowIndex + 1}
      </div>
      <Spacer width={leftPad} />
      {columnItems.map((item) => {
        const cell = getCell(rowIndex, item.columnIndex)
        const isActive = activeColumnIndex === item.columnIndex
        return (
          <div
            key={item.columnIndex}
            role="gridcell"
            aria-rowindex={rowIndex + 1}
            aria-colindex={item.columnIndex + 1}
            className={cn(
              "flex items-center truncate border-r px-2 last:border-r-0",
              cell.numeric ? "justify-end tabular-nums" : "justify-start",
              isActive && "bg-primary/12 ring-1 ring-primary/50 ring-inset"
            )}
            title={cell.text}
          >
            <span className="truncate">{cell.text}</span>
          </div>
        )
      })}
      <Spacer width={rightPad} />
    </div>
  )
})

export function Spacer({ width }: { width: number }) {
  return <div aria-hidden style={{ width }} />
}

"use client"

import * as React from "react"

export const XLSX_SCROLLBAR_CSS = `
[data-slot="xlsx-body"]::-webkit-scrollbar { width: 10px; height: 10px; }
[data-slot="xlsx-body"]::-webkit-scrollbar:vertical { display: none; }
[data-slot="xlsx-body"]::-webkit-scrollbar-track { background: transparent; }
[data-slot="xlsx-body"]::-webkit-scrollbar-thumb {
  background-color: color-mix(in oklab, var(--foreground) 22%, transparent);
  border-radius: 9999px;
  border: 3px solid transparent;
  background-clip: content-box;
}
[data-slot="xlsx-body"]::-webkit-scrollbar-thumb:hover {
  background-color: color-mix(in oklab, var(--foreground) 38%, transparent);
}
`

export function HeaderAwareScrollbar({
  scrollRef,
  headerHeight,
}: {
  scrollRef: React.RefObject<HTMLDivElement | null>
  headerHeight: number
}) {
  const [thumb, setThumb] = React.useState({ height: 0, top: 0, show: false })
  const drag = React.useRef<{ y: number; scroll: number } | null>(null)

  const measure = React.useCallback(() => {
    const element = scrollRef.current
    if (!element) return
    const { scrollHeight, clientHeight, scrollTop } = element
    const track = clientHeight - headerHeight
    if (scrollHeight <= clientHeight + 1 || track <= 0) {
      setThumb((value) => (value.show ? { ...value, show: false } : value))
      return
    }
    const height = Math.max(28, (clientHeight / scrollHeight) * track)
    const maxScroll = scrollHeight - clientHeight
    const top = maxScroll > 0 ? (scrollTop / maxScroll) * (track - height) : 0
    setThumb({ height, top, show: true })
  }, [scrollRef, headerHeight])

  React.useEffect(() => {
    const element = scrollRef.current
    if (!element) return
    measure()
    element.addEventListener("scroll", measure, { passive: true })
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => {
      element.removeEventListener("scroll", measure)
      observer.disconnect()
    }
  }, [scrollRef, measure])

  const onPointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    const element = scrollRef.current
    if (!element) return
    event.preventDefault()
    drag.current = { y: event.clientY, scroll: element.scrollTop }
    event.currentTarget.setPointerCapture(event.pointerId)
  }
  const onPointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const element = scrollRef.current
    const currentDrag = drag.current
    if (!element || !currentDrag) return
    const track = element.clientHeight - headerHeight
    const height = Math.max(
      28,
      (element.clientHeight / element.scrollHeight) * track
    )
    const denominator = track - height
    if (denominator <= 0) return
    const maxScroll = element.scrollHeight - element.clientHeight
    element.scrollTop =
      currentDrag.scroll +
      ((event.clientY - currentDrag.y) / denominator) * maxScroll
  }
  const endDrag = (event: React.PointerEvent<HTMLDivElement>) => {
    drag.current = null
    event.currentTarget.releasePointerCapture?.(event.pointerId)
  }

  if (!thumb.show) return null
  return (
    <div
      aria-hidden
      className="pointer-events-none absolute right-0 z-30 w-2.5"
      style={{ top: headerHeight, bottom: 0 }}
    >
      <div
        className="pointer-events-auto absolute right-0.5 w-1.5 rounded-full bg-foreground/25 transition-colors hover:bg-foreground/40"
        style={{ height: thumb.height, top: thumb.top }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
      />
    </div>
  )
}

